}

.app-map__hint {
  margin-top: var(--zh-size-mini);
}

/* ---- Detail panel (aside/dialog) ---- */
.app-detail {
  position: fixed;
  z-index: var(--zh-z-detail);
  inset: 0;
  background: var(--zh-white);
  overflow: auto;
  border-left: var(--zh-rule) solid var(--zh-black);
  box-shadow: var(--zh-shadow-card);

