import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BASE = 'http://127.0.0.1:8787';
const PORT = 9333;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const profile = await mkdtemp(path.join(os.tmpdir(), 'point-probe-'));
const chrome = spawn('chromium', [
  '--headless=new', `--remote-debugging-port=${PORT}`, `--user-data-dir=${profile}`,
  '--no-first-run', '--no-default-browser-check', '--disable-gpu', '--window-size=1440,1000', 'about:blank',
], { stdio: 'ignore' });

let version;
for (let i = 0; i < 40; i++) {
  try { version = await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json(); break; } catch { await sleep(250); }
}
const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((res) => ws.addEventListener('open', res, { once: true }));
let id = 0; const pending = new Map();
ws.addEventListener('message', (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); }
});
const send = (method, params = {}, sessionId) => new Promise((resolve, reject) => { const i = ++id; pending.set(i, { resolve, reject }); ws.send(JSON.stringify({ id: i, method, params, sessionId })); });
const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
const S = (m, p) => send(m, p, sessionId);
await S('Page.enable'); await S('Runtime.enable');
const evalIn = async (expr) => (await S('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true })).result.value;
await S('Page.navigate', { url: BASE + '/' });
await sleep(2500);

const initial = await evalIn(`({ rows: document.querySelectorAll('#result-list > *').length, url: location.search })`);

// 1. keyboard route: focus map and press "p" -> point filter at map centre (Zürich)
await evalIn(`document.querySelector('#map').focus()`);
await S('Input.dispatchKeyEvent', { type: 'keyDown', key: 'p', code: 'KeyP', text: 'p' });
await S('Input.dispatchKeyEvent', { type: 'keyUp', key: 'p', code: 'KeyP' });
await sleep(700);
const afterKey = await evalIn(`(() => { const b = document.querySelector('#point-filter'); return { url: location.search, chipHidden: b.hidden, chip: document.querySelector('#point-filter-text').textContent, rows: document.querySelectorAll('#result-list > *').length, crosshair: Boolean(document.querySelector('.map-point')), marker: document.querySelector('#point-filter-clear')?.getAttribute('aria-label') }; })()`);

// 2. clear the filter again
await evalIn(`document.querySelector('#point-filter-clear').click()`);
await sleep(500);
const afterClear = await evalIn(`({ url: location.search, chipHidden: document.querySelector('#point-filter').hidden, rows: document.querySelectorAll('#result-list > *').length, crosshair: Boolean(document.querySelector('.map-point')) })`);

// 3. map click sets a point (click the centre of the map)
const box = await evalIn(`(() => { const r = document.querySelector('#map').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
await S('Input.dispatchMouseEvent', { type: 'mousePressed', x: box.x, y: box.y, button: 'left', clickCount: 1 });
await S('Input.dispatchMouseEvent', { type: 'mouseReleased', x: box.x, y: box.y, button: 'left', clickCount: 1 });
await sleep(700);
const afterClick = await evalIn(`({ url: location.search, chipHidden: document.querySelector('#point-filter').hidden, chip: document.querySelector('#point-filter-text').textContent, rows: document.querySelectorAll('#result-list > *').length, crosshair: Boolean(document.querySelector('.map-point')) })`);

// 4. a shared ?at= URL reproduces the filter
await S('Page.navigate', { url: `${BASE}/?at=46.9480%2C7.4474` });
await sleep(2200);
const shared = await evalIn(`({ url: location.search, chipHidden: document.querySelector('#point-filter').hidden, chip: document.querySelector('#point-filter-text').textContent, rows: document.querySelectorAll('#result-list > *').length, crosshair: Boolean(document.querySelector('.map-point')) })`);

// 5. a point outside every footprint shows the honest empty state
await S('Page.navigate', { url: `${BASE}/?at=52.5200%2C13.4050` });
await sleep(2200);
const empty = await evalIn(`({ rows: document.querySelectorAll('#result-list > *').length, state: document.querySelector('#results-state')?.hidden === false, text: document.querySelector('#results-state')?.textContent.slice(0, 200), remove: [...document.querySelectorAll('#results-state button')].map(b => b.textContent.trim()) })`);

// 6. place search offers the "Karten an diesem Ort" chip
await S('Page.navigate', { url: `${BASE}/` });
await sleep(2200);
await evalIn(`(() => { const input = document.querySelector('#place-input'); input.focus(); input.value = 'Rheinau'; input.dispatchEvent(new Event('input', { bubbles: true })); return true; })()`);
await sleep(1800);
await S('Input.dispatchKeyEvent', { type: 'keyDown', key: 'ArrowDown', code: 'ArrowDown' });
await S('Input.dispatchKeyEvent', { type: 'keyUp', key: 'ArrowDown', code: 'ArrowDown' });
await S('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Enter', code: 'Enter' });
await S('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Enter', code: 'Enter' });
await sleep(1200);
const placeChip = await evalIn(`(() => { const wrap = document.querySelector('#place-status + .zh-quickranges'); const chip = wrap?.querySelector('button'); return { status: document.querySelector('#place-status').textContent.slice(0, 120), hidden: wrap?.hidden, chip: chip?.textContent, pressed: chip?.getAttribute('aria-pressed') }; })()`);
if (placeChip.chip) {
  await evalIn(`document.querySelector('#place-status + .zh-quickranges button').click()`);
  await sleep(800);
}
const placeApplied = await evalIn(`({ url: location.search, chipHidden: document.querySelector('#point-filter').hidden, chip: document.querySelector('#point-filter-text').textContent, rows: document.querySelectorAll('#result-list > *').length })`);

console.log(JSON.stringify({ initial, afterKey, afterClear, afterClick, shared, empty, placeChip, placeApplied }, null, 1));
chrome.kill('SIGKILL');
process.exit(0);

