export function clusterByCell(points, cellPx = CLUSTER_CELL) {
  const cells = new Map();
  for (const point of points ?? []) {
    const key = `${Math.floor(point.x / cellPx)}:${Math.floor(point.y / cellPx)}`;
    let cell = cells.get(key);
    if (!cell) {
      cell = { key, x: 0, y: 0, count: 0, members: [] };
      cells.set(key, cell);
    }
    cell.x += point.x;
    cell.y += point.y;
    cell.count += 1;
    cell.members.push(point);
  }
  return [...cells.values()].map((cell) => ({ ...cell, x: cell.x / cell.count, y: cell.y / cell.count }));
}

/** Metres per screen pixel in Web Mercator (256 px tiles) at a latitude/zoom. */
export function metresPerPixel(lat, zoom) {
  const latitude = Number.isFinite(lat) ? Math.max(-85, Math.min(85, lat)) : 0;
  const z = Number.isFinite(zoom) ? Math.max(0, Math.min(22, zoom)) : 2;
  return (156543.03392 * Math.cos((latitude * Math.PI) / 180)) / 2 ** z;
}

/** Round distances (0.1 m … 5,000 km) a scale bar is allowed to show. */
const SCALE_STEPS = [1, 2, 5].flatMap((base) => Array.from({ length: 9 }, (_, i) => base * 10 ** (i - 1)));

/**
 * Scale-bar segment for the current latitude/zoom: the largest round distance
 * whose segment still fits in `maxPx`. Pure, therefore unit-tested; `map.js`
 * renders exactly what this returns (never a guessed distance).
 */
export function scaleBarSpec(lat, zoom, maxPx = 120) {
  const mpp = metresPerPixel(lat, zoom);
  if (!Number.isFinite(mpp) || mpp <= 0) return null;
  const limit = Number.isFinite(maxPx) && maxPx > 8 ? maxPx : 120;
  const fits = SCALE_STEPS.filter((metres) => metres / mpp <= limit);
  const metres = fits.length > 0 ? fits[fits.length - 1] : SCALE_STEPS[0];
  const km = metres / 1000;
  return {
    metres,
    px: Math.min(limit, Math.max(1, Math.round(metres / mpp))),
    label: metres >= 1000 ? `${Number(km.toFixed(Number.isInteger(km) ? 0 : 1))} km` : `${metres} m`,
  };
}

