edits.newText:
test('an empty record set produces no clusters', () => {
  assert.deepEqual(clusterByCell([]), []);
  assert.deepEqual(clusterByCell(undefined), []);
});

/* ---------- scale bar ---------- */

test('metres per pixel follows the Web Mercator / latitude curve', () => {
  const equator = metresPerPixel(0, 0);
  assert.ok(Math.abs(equator - 156543.03392) < 1e-6);
  assert.ok(Math.abs(metresPerPixel(0, 1) - equator / 2) < 1e-6, 'one zoom level halves the ground resolution');
  assert.ok(metresPerPixel(60, 10) < metresPerPixel(0, 10), 'higher latitude = fewer metres per pixel');
  assert.ok(Number.isFinite(metresPerPixel(NaN, NaN)), 'broken input still returns a usable value');
});

test('the scale bar picks a round distance that fits the bar', () => {
  const zurich = scaleBarSpec(47.3769, 12);
  assert.equal(zurich.label, '2 km');
  assert.ok(zurich.px >= 40 && zurich.px <= 120, `${zurich.px}px must stay inside the bar budget`);
  const deep = scaleBarSpec(47.3769, 14);
  assert.equal(deep.label, '500 m');
  assert.ok(deep.px >= 40 && deep.px <= 120);
  assert.ok(deep.metres < zurich.metres, 'zooming in shows a smaller distance');
  const world = scaleBarSpec(0, 2);
  assert.equal(world.label, '2000 km');
  assert.ok(world.px <= 120);
});

test('the scale bar label is human, never a raw float', () => {
  for (const zoom of [2, 5, 8, 11, 14, 17]) {
    const spec = scaleBarSpec(47.3769, zoom);
    assert.match(spec.label, /^\d+(?:\.\d)? (m|km)$/);
    assert.equal(Number.isInteger(spec.px), true);
  }
});

